export async function getMonitorCheck(
  http: HttpClient,
  monitorId: string,
  checkId: string,
  options?: GetMonitorCheckOptions,
): Promise<MonitorCheckDetail> {
  try {
    const { autoPaginate: _autoPaginate, maxPages: _maxPages, maxResults: _maxResults, maxWaitTime: _maxWaitTime, ...query } = options ?? {};
    const res = await http.get<ApiResponse<MonitorCheckDetail>>(
      `/v2/monitor/${monitorId}/checks/${checkId}${queryString(query as Record<string, unknown>)}`,
    );
    const detail = dataOrThrow(res, "get monitor check");
    const next = res.data?.next ?? detail.next ?? null;
    const auto = options?.autoPaginate ?? true;
    if (!auto || !next) {
      return { ...detail, next };
    }

    return {
      ...detail,
      pages: await fetchAllPages<MonitorCheckPage>(
        http,
        next,
        detail.pages || [],
        options,
      ),
      next: null,
    };
  } catch (err: any) {
    if (err?.isAxiosError) return normalizeAxiosError(err, "get monitor check");
    throw err;
  }
}

import { type Document, type ParseFile, type ParseOptions } from "../types";
import { HttpClient } from "../utils/httpClient";
import { ensureValidParseOptions } from "../utils/validation";
import {
  throwForBadResponse,
  normalizeAxiosError,
} from "../utils/errorHandler";
import { getVersion } from "../utils/getVersion";

function toUploadBlob(input: ParseFile["data"], contentType?: string): Blob {
  if (typeof Blob !== "undefined" && input instanceof Blob) {
    if (contentType && input.type !== contentType) {
      return new Blob([input], { type: contentType });
    }
    return input;
  }

  if (typeof Buffer !== "undefined" && Buffer.isBuffer(input)) {
    return new Blob([input], { type: contentType });
  }

  if (input instanceof ArrayBuffer) {
    return new Blob([input], { type: contentType });
  }

  if (ArrayBuffer.isView(input)) {
    return new Blob([input], { type: contentType });
  }

  if (typeof input === "string") {
    return new Blob([input], {
      type: contentType ?? "text/plain; charset=utf-8",
    });
  }

  throw new Error("Unsupported parse file data type");
}

export async function parse(
  http: HttpClient,
  file: ParseFile,
  options?: ParseOptions,
): Promise<Document> {
  if (!file || !file.filename || !file.filename.trim()) {
    throw new Error("filename cannot be empty");
  }

  if (file.data == null) {
    throw new Error("file data cannot be empty");
  }

  const blob = toUploadBlob(file.data, file.contentType);
  if (blob.size === 0) {
    throw new Error("file data cannot be empty");
  }

  if (options) ensureValidParseOptions(options);

  const version = getVersion();
  const normalizedOptions: ParseOptions = {
    ...(options ?? {}),
    origin:
      typeof options?.origin === "string" && options.origin.includes("mcp")
        ? options.origin
        : (options?.origin ?? `js-sdk@${version}`),
  };

  const formData = new FormData();
  formData.append("options", JSON.stringify(normalizedOptions));
  formData.append(
    "file",
    toUploadBlob(file.data, file.contentType),
    file.filename.trim(),
  );

  try {
    const res = await http.postMultipart<{
      success: boolean;
      data?: Document;
      error?: string;
    }>(
      "/v2/parse",
      formData,
      typeof normalizedOptions.timeout === "number"
        ? { timeoutMs: normalizedOptions.timeout + 5000 }
        : {},
    );
    if (res.status !== 200 || !res.data?.success) {
      throwForBadResponse(res, "parse");
    }
    return (res.data.data || {}) as Document;
  } catch (err: any) {
    if (err?.isAxiosError) return normalizeAxiosError(err, "parse");
    throw err;
  }
}

import type {
  SearchPapersOptions,
  SearchPapersResponse,
  GetPaperOptions,
  PaperMetadataResponse,
  ReadPaperResponse,
  SimilarPapersOptions,
  SimilarPapersResponse,
  SearchGithubOptions,
  GitHubSearchResponse,
} from "../types";
import { SdkError } from "../types";
import { HttpClient } from "../utils/httpClient";
import { throwForBadResponse } from "../utils/errorHandler";
import { getVersion } from "../utils/getVersion";

const BASE = "/v2/search/research";

/** Append a value (or repeated array values) to a URLSearchParams instance. */
function appendParam(
  params: URLSearchParams,
  key: string,
  value: string | number | boolean | string[] | undefined,
): void {
  if (value == null) return;
  if (Array.isArray(value)) {
    for (const v of value) {
      if (v != null && String(v).length > 0) params.append(key, String(v));
    }
  } else {
    params.append(key, String(value));
  }
}

function withQuery(path: string, params: URLSearchParams): string {
  // Research endpoints are GETs, so the POST-body origin injection in
  // HttpClient never applies — attach it as a query param instead.
  params.append("origin", `js-sdk@${getVersion()}`);
  const qs = params.toString();
  return qs ? `${path}?${qs}` : path;
}

/**
 * Translate the RFC 7807 Problem body returned by the research service into an
 * SdkError. Falls back to the generic axios normalization otherwise.
 */
function normalizeResearchError(err: any, action: string): never {
  if (err?.isAxiosError) {
    const status: number | undefined = err.response?.status;
    const body: any = err.response?.data;
    if (body && (body.detail || body.title)) {
      const message = body.detail || body.title;
      throw new SdkError(message, status, body.type, body);
    }
    throw new SdkError(
      err.message || `Request failed while trying to ${action}`,
      status,
      err.code,
      body,
    );
  }
  throw err;
}

/**
 * Client for the v2 research endpoints — Firecrawl's **research paper index**
 * (~43M paper abstracts) plus GitHub history/readmes.
 *
 * The paper corpus is roughly 90% biomedical and life sciences — PubMed,
 * bioRxiv and medRxiv — with arXiv covering physics, mathematics and computer
 * science. Supports abstract search, paper metadata, in-body passage reads and
 * citation-graph expansion.
 *
 * ⚠️ This is **not** the same as `search({ categories: ["research"] })`. That
 * option is a website/domain filter on ordinary web search: it narrows
 * Google-style results to ~14 academic domains and returns page snippets. The
 * methods here query the paper index itself and return ranked paper records.
 *
 * Accessed via `firecrawl.research`.
 *
 * @example
 * ```ts
 * const res = await firecrawl.research.searchPapers(
 *   "tau aggregation inhibitors in Alzheimer's disease",
 *   { k: 10 },
 * );
 * ```
 */
export class ResearchClient {
  constructor(private readonly http: HttpClient) {}

  /**
   * Search the research paper index by abstract relevance.
   *
   * Queries ~43M paper abstracts: PubMed, bioRxiv and medRxiv (about 90% of the
   * corpus — biomedical and life sciences) plus arXiv (physics, mathematics,
   * computer science). Semantic search over abstracts, not keyword matching.
   *
   * This is **not** `search({ categories: ["research"] })`, which only narrows
   * ordinary web search to ~14 academic websites.
   *
   * @param query Natural-language search query, e.g. `"CRISPR base editing
   *   off-target effects in primary human T cells"`.
   * @param options Optional filters (k, authors, categories, from, to). Note
   *   `categories` here filters *paper* subject categories (e.g. `"q-bio.GN"`)
   *   and is unrelated to the `categories` option of `search()`.
   */
  async searchPapers(
    query: string,
    options: SearchPapersOptions = {},
  ): Promise<SearchPapersResponse> {
    if (!query || !query.trim()) throw new Error("query cannot be empty");
    if (options.k != null && options.k <= 0)
      throw new Error("k must be positive");
    const params = new URLSearchParams();
    appendParam(params, "query", query);
    appendParam(params, "k", options.k);
    appendParam(params, "authors", options.authors);
    appendParam(params, "categories", options.categories);
    appendParam(params, "from", options.from);
    appendParam(params, "to", options.to);
    try {
      const res = await this.http.get<SearchPapersResponse>(
        withQuery(`${BASE}/papers`, params),
      );
      if (res.status !== 200) throwForBadResponse(res, "search papers");
      return res.data;
    } catch (err) {
      return normalizeResearchError(err, "search papers");
    }
  }

  /**
   * Get paper metadata (detail mode), or read in-body passages (when `query` is
   * supplied). `k` is only valid together with `query`.
   * @param id Paper reference: a canonical `paperId`, or a namespaced id key
   *   such as `pmid:<id>`, `pmcid:<id>`, `doi:<doi>` or `arxiv:<id>`. Bare
   *   arXiv ids and arXiv URLs are also accepted.
   * @param options Optional `query` (switches to read mode) and `k`.
   */
  async getPaper(
    id: string,
    options?: { query?: undefined; k?: undefined },
  ): Promise<PaperMetadataResponse>;
  async getPaper(
    id: string,
    options: { query: string; k?: number },
  ): Promise<ReadPaperResponse>;
  async getPaper(
    id: string,
    options: GetPaperOptions = {},
  ): Promise<PaperMetadataResponse | ReadPaperResponse> {
    if (!id || !id.trim()) throw new Error("id cannot be empty");
    if (options.k != null && options.query == null)
      throw new Error("k is only valid together with query");
    if (options.k != null && options.k <= 0)
      throw new Error("k must be positive");
    const params = new URLSearchParams();
    appendParam(params, "query", options.query);
    appendParam(params, "k", options.k);
    try {
      const res = await this.http.get<PaperMetadataResponse | ReadPaperResponse>(
        withQuery(`${BASE}/papers/${encodeURIComponent(id)}`, params),
      );
      if (res.status !== 200) throwForBadResponse(res, "get paper");
      return res.data;
    } catch (err) {
      return normalizeResearchError(err, "get paper");
    }
  }

  /**
   * Find related papers via the citation graph.
   * @param id Primary seed paper reference.
   * @param options Required `intent` plus optional mode, k, rerank, anchor.
   */
  async similarPapers(
    id: string,
    options: SimilarPapersOptions,
  ): Promise<SimilarPapersResponse> {
    if (!id || !id.trim()) throw new Error("id cannot be empty");
    if (!options?.intent || !options.intent.trim())
      throw new Error("intent cannot be empty");
    if (options.k != null && options.k <= 0)
      throw new Error("k must be positive");
    const params = new URLSearchParams();
    appendParam(params, "intent", options.intent);
    appendParam(params, "mode", options.mode);
    appendParam(params, "k", options.k);
    if (options.rerank != null) appendParam(params, "rerank", options.rerank);
    appendParam(params, "anchor", options.anchor);
    try {
      const res = await this.http.get<SimilarPapersResponse>(
        withQuery(
          `${BASE}/papers/${encodeURIComponent(id)}/similar`,
          params,
        ),
      );
      if (res.status !== 200) throwForBadResponse(res, "find similar papers");
      return res.data;
    } catch (err) {
      return normalizeResearchError(err, "find similar papers");
    }
  }

  /**
   * Search GitHub issue/PR history and repository readmes.
   * @param query Search query.
   * @param options Optional `k`.
   */
  async searchGithub(
    query: string,
    options: SearchGithubOptions = {},
  ): Promise<GitHubSearchResponse> {
    if (!query || !query.trim()) throw new Error("query cannot be empty");
    if (options.k != null && options.k <= 0)
      throw new Error("k must be positive");
    const params = new URLSearchParams();
    appendParam(params, "query", query);
    appendParam(params, "k", options.k);
    try {
      const res = await this.http.get<GitHubSearchResponse>(
        withQuery(`${BASE}/github`, params),
      );
      if (res.status !== 200) throwForBadResponse(res, "search github");
      return res.data;
    } catch (err) {
      return normalizeResearchError(err, "search github");
    }
  }
}

import {
  type Document,
  type ScrapeBrowserDeleteResponse,
  type ScrapeExecuteRequest,
  type ScrapeExecuteResponse,
  type ScrapeOptions,
} from "../types";
import { HttpClient } from "../utils/httpClient";
import { ensureValidScrapeOptions } from "../utils/validation";
import {
  throwForBadResponse,
  normalizeAxiosError,
} from "../utils/errorHandler";

/** Auto-resume bounds: a resume only ever follows the server's explicit
 * "processing continues" signal, and stops after this many resumes or
 * this much total sleeping — whichever comes first. */
const RESUME_MAX_ATTEMPTS = 5;
const RESUME_MAX_TOTAL_WAIT_MS = 20 * 60 * 1000;
const RESUME_MIN_DELAY_MS = 5 * 1000;
const RESUME_MAX_DELAY_MS = 10 * 60 * 1000;

/**
 * When a request failed because the document is still processing
 * server-side (large PDFs outlive their request window by design), the
 * error carries `details.state === "processing_continues"` plus a retry
 * delay. Returns that delay in ms, or undefined for every other error.
 */
export function processingContinuesDelayMs(err: unknown): number | undefined {
  const response = (err as { isAxiosError?: boolean; response?: any })
    ?.isAxiosError
    ? (err as { response?: any }).response
    : undefined;
  if (!response || response.status !== 408) return undefined;
  const body = response.data as
    | { code?: string; details?: { state?: string; retryAfterSeconds?: number } }
    | undefined;
  if (
    body?.code !== "SCRAPE_TIMEOUT" ||
    body?.details?.state !== "processing_continues"
  ) {
    return undefined;
  }
  const headerSeconds = Number(response.headers?.["retry-after"]);
  const seconds =
    typeof body.details.retryAfterSeconds === "number" &&
    Number.isFinite(body.details.retryAfterSeconds)
      ? body.details.retryAfterSeconds
      : Number.isFinite(headerSeconds)
        ? headerSeconds
        : 60;
  return Math.min(RESUME_MAX_DELAY_MS, Math.max(RESUME_MIN_DELAY_MS, seconds * 1000));
}

/**
 * Options for a direct scrape call. `autoResume` lives here — NOT on the
 * shared ScrapeOptions — because that type is reused verbatim inside
 * batch/crawl/search/extract payloads, where an SDK-only key would leak
 * onto the wire and fail strict endpoints.
 */
export type ScrapeCallOptions = ScrapeOptions & {
  /**
   * SDK-only (never sent to the API). Large documents (big PDFs) that
   * outlive the request window keep processing server-side; the API's
   * timeout error then carries `details.state === "processing_continues"`
   * and a Retry-After. When this is not `false`, the SDK sleeps that
   * long and re-issues the same request — the retry attaches to the
   * in-flight job and returns the finished result, so a large document
   * behaves like one slow successful call. Bounded (at most 5 resumes /
   * 20 minutes total wait); set `false` to surface the timeout error
   * immediately instead.
   */
  autoResume?: boolean;
};

export async function scrape(
  http: HttpClient,
  url: string,
  options?: ScrapeCallOptions,
  deps: { sleepImpl?: (ms: number) => Promise<void> } = {},
): Promise<Document> {
  const sleep =
    deps.sleepImpl ??
    ((ms: number) => new Promise<void>(resolve => setTimeout(resolve, ms)));
  if (!url || !url.trim()) {
    throw new Error("URL cannot be empty");
  }
  if (options) ensureValidScrapeOptions(options);

  // autoResume is SDK behavior, never part of the wire payload.
  const { autoResume, ...requestOptions } = options ?? {};
  const payload: Record<string, unknown> = { url: url.trim() };
  Object.assign(payload, requestOptions);

  // Per-request timeout. With auto-resume disabled this is exactly the
  // pre-existing behavior (explicit timeout +5s, else the client's own
  // default). With auto-resume on, the client-side timeout must outlast
  // the SERVER's wall — options.timeout, or the API's 5-minute default —
  // otherwise axios can abort in a photo-finish with the server's
  // processing_continues response and the resume signal is lost exactly
  // when it matters. The caller's configured client timeout is
  // respected as a floor, never overridden downward.
  const requestTimeout: { timeoutMs?: number } =
    autoResume === false
      ? typeof options?.timeout === "number"
        ? { timeoutMs: options.timeout + 5000 }
        : {}
      : {
          timeoutMs:
            Math.max(
              typeof options?.timeout === "number" ? options.timeout : 300_000,
              typeof http.getTimeoutMs === "function" ? http.getTimeoutMs() : 0,
            ) + 30_000,
        };

  let resumes = 0;
  let resumeWaitedMs = 0;
  while (true) {
    try {
      const res = await http.post<{
        success: boolean;
        data?: Document;
        error?: string;
      }>(
        "/v2/scrape",
        payload,
        requestTimeout,
      );
      if (res.status !== 200 || !res.data?.success) {
        throwForBadResponse(res, "scrape");
      }
      return (res.data.data || {}) as Document;
    } catch (err: any) {
      const delayMs = autoResume !== false ? processingContinuesDelayMs(err) : undefined;
      if (
        delayMs !== undefined &&
        resumes < RESUME_MAX_ATTEMPTS &&
        resumeWaitedMs + delayMs <= RESUME_MAX_TOTAL_WAIT_MS
      ) {
        // The document keeps processing server-side; the retry attaches
        // to the same in-flight job (content adoption) and returns the
        // finished result instead of restarting the work.
        resumes += 1;
        resumeWaitedMs += delayMs;
        await sleep(delayMs);
        continue;
      }
      if (err?.isAxiosError) return normalizeAxiosError(err, "scrape");
      throw err;
    }
  }
}

export async function interact(
  http: HttpClient,
  jobId: string,
  args: ScrapeExecuteRequest,
): Promise<ScrapeExecuteResponse> {
  if (!jobId || !jobId.trim()) {
    throw new Error("Job ID cannot be empty");
  }
  const hasCode = args?.code && args.code.trim();
  const hasPrompt = args?.prompt && args.prompt.trim();
  if (!hasCode && !hasPrompt) {
    throw new Error("Either 'code' or 'prompt' must be provided");
  }

  const body: Record<string, unknown> = {};
  if (hasCode) body.code = args.code;
  if (hasPrompt) body.prompt = args.prompt;
  body.language = args.language ?? "node";
  if (args.timeout != null) body.timeout = args.timeout;
  if (args.origin) body.origin = args.origin;

  try {
    const res = await http.post<ScrapeExecuteResponse>(
      `/v2/scrape/${jobId}/interact`,
      body,
      args.timeout != null ? { timeoutMs: args.timeout * 1000 + 5000 } : {},
    );
    if (res.status !== 200)
      throwForBadResponse(res, "interact with scrape browser");
    return res.data;
  } catch (err: any) {
    if (err?.isAxiosError)
      return normalizeAxiosError(err, "interact with scrape browser");
    throw err;
  }
}

export async function stopInteraction(
  http: HttpClient,
  jobId: string,
): Promise<ScrapeBrowserDeleteResponse> {
  if (!jobId || !jobId.trim()) {
    throw new Error("Job ID cannot be empty");
  }

  try {
    const res = await http.delete<ScrapeBrowserDeleteResponse>(
      `/v2/scrape/${jobId}/interact`,
    );
    if (res.status !== 200) throwForBadResponse(res, "stop interaction");
    return res.data;
  } catch (err: any) {
    if (err?.isAxiosError) return normalizeAxiosError(err, "stop interaction");
    throw err;
  }
}

